/// <reference types="node" />
// src/lib/rules.ts를 supabase/functions/_shared/rules.ts로 복사한다. `npm run sync:rules`.
// 사본은 맨 위 생성 표시 줄만 다르다. src/lib/__tests__/rules-sync.test.ts가 같은지 검사한다.
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';

export const GENERATED_HEADER =
  '// GENERATED by `npm run sync:rules` from src/lib/rules.ts. Do not edit this file; edit the source and re-run.\n';

const ROOT = join(__dirname, '..');
const SRC = join(ROOT, 'src', 'lib', 'rules.ts');
const DEST = join(ROOT, 'supabase', 'functions', '_shared', 'rules.ts');

function main() {
  mkdirSync(dirname(DEST), { recursive: true });
  writeFileSync(DEST, GENERATED_HEADER + readFileSync(SRC, 'utf8'));
  process.stdout.write(`sync:rules ${DEST}\n`);
}

if (require.main === module) main();
